import operator
import re

from .version import Version

_OPERATORS = ("<=", ">=", "<", ">", "=")
_OPERATOR_ONLY = frozenset(_OPERATORS)
_COMPARE = {
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
    "=": operator.eq,
}
_COMPARATOR = re.compile(r"^(<=|>=|<|>|=)?(.*)$")
_NUMBER = re.compile(r"^(0|[1-9]\d*)$")
_PRE_ID = re.compile(r"^(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)$")
_BUILD = re.compile(r"^[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*$")
_WILDCARDS = ("x", "X", "*")


class _Partial:
    """A parsed version or partial version. ``None`` marks a wildcard or missing position."""

    __slots__ = ("major", "minor", "patch", "pre")

    def __init__(self, major, minor, patch, pre):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.pre = pre

    @property
    def is_full(self):
        return self.major is not None and self.minor is not None and self.patch is not None

    @property
    def release(self):
        return (self.major, self.minor, self.patch)

    def lower(self):
        """The smallest version this (partial) version stands for."""
        return Version(self.major or 0, self.minor or 0, self.patch or 0, self.pre)

    def next_boundary(self):
        """The first release above everything this partial version covers, or None if unbounded."""
        if self.major is None:
            return None
        if self.minor is None:
            return Version(self.major + 1, 0, 0)
        if self.patch is None:
            return Version(self.major, self.minor + 1, 0)
        return Version(self.major, self.minor, self.patch + 1)


def _parse_partial(text, original):
    """Parse ``1.2.3-pre+build``, ``1.2``, ``1.x``, ``*`` and friends."""
    body = text[1:] if text[:1] == "v" else text
    body, plus, build = body.partition("+")
    if plus and not _BUILD.match(build):
        raise ValueError(f"invalid version in range: {original!r}")

    core, dash, pre_text = body.partition("-")
    pre = ()
    if dash:
        if not all(_PRE_ID.match(i) for i in pre_text.split(".")) or not pre_text:
            raise ValueError(f"invalid prerelease in range: {original!r}")
        pre = tuple(pre_text.split("."))

    parts = core.split(".")
    if not 1 <= len(parts) <= 3:
        raise ValueError(f"invalid version in range: {original!r}")

    values = []
    wildcard = False
    for part in parts:
        if part in _WILDCARDS:
            wildcard = True
            values.append(None)
        elif wildcard or not _NUMBER.match(part):
            # A number after a wildcard (1.x.3) or any junk is invalid.
            raise ValueError(f"invalid version in range: {original!r}")
        else:
            values.append(int(part))
    while len(values) < 3:
        values.append(None)

    if pre and None in values:
        raise ValueError(f"prerelease needs a full version: {original!r}")
    return _Partial(values[0], values[1], values[2], pre)


def _comparator_bounds(op, p):
    """Turn one comparator into ``(op, Version)`` bounds.

    Returns ``None`` when the comparator can match nothing.
    """
    if p.major is None:
        # Wildcard: every version, except that strict comparisons with a wildcard match nothing.
        return None if op in (">", "<") else []

    lo = p.lower()
    hi = p.next_boundary()
    full = p.is_full

    if op in ("", "="):
        return [("=", lo)] if full else [(">=", lo), ("<", hi)]
    if op == ">":
        return [(">", lo)] if full else [(">=", hi)]
    if op == ">=":
        return [(">=", lo)]
    if op == "<":
        return [("<", lo)]
    if op == "<=":
        return [("<=", lo)] if full else [("<", hi)]
    raise AssertionError(op)  # pragma: no cover - operators are validated by the caller


def _tilde_bounds(p):
    if p.major is None:
        return []
    upper = Version(p.major, p.minor + 1, 0) if p.minor is not None else Version(p.major + 1, 0, 0)
    return [(">=", p.lower()), ("<", upper)]


def _caret_bounds(p):
    if p.major is None:
        return []
    if p.major != 0 or p.minor is None:
        upper = Version(p.major + 1, 0, 0)
    elif p.minor != 0:
        upper = Version(0, p.minor + 1, 0)
    elif p.patch is None:
        upper = Version(0, 1, 0)
    else:
        upper = Version(0, 0, p.patch + 1)
    return [(">=", p.lower()), ("<", upper)]


def _hyphen_bounds(a, b):
    bounds = []
    if a.major is not None:
        bounds.append((">=", a.lower()))
    if b.major is not None:
        if b.is_full:
            bounds.append(("<=", b.lower()))
        else:
            bounds.append(("<", b.next_boundary()))
    return bounds


def _parse_set(text):
    """Parse one comparator set into ``(bounds, anchors)``.

    ``bounds`` is a list of ``(op, Version)``; ``anchors`` is the set of release
    tuples that some comparator names with a prerelease tag.
    """
    tokens = []
    raw = text.split()
    i = 0
    while i < len(raw):
        token = raw[i]
        if token in _OPERATOR_ONLY:
            if i + 1 >= len(raw):
                raise ValueError(f"operator without version in range: {text!r}")
            token += raw[i + 1]
            i += 2
        else:
            i += 1
        tokens.append(token)

    bounds = []
    anchors = set()
    never = False
    i = 0
    while i < len(tokens):
        if i + 2 < len(tokens) and tokens[i + 1] == "-":
            a = _parse_partial(tokens[i], text)
            b = _parse_partial(tokens[i + 2], text)
            bounds.extend(_hyphen_bounds(a, b))
            parsed = (a, b)
            i += 3
        else:
            match = _COMPARATOR.match(tokens[i])
            op, body = match.group(1) or "", match.group(2)
            if not body:
                raise ValueError(f"operator without version in range: {text!r}")
            p = _parse_partial(body, text)
            parsed = (p,)
            if body[:1] in _WILDCARDS or op in ("", "=", ">=", "<="):
                pass
            if op in ("~", "^"):  # not reachable; tilde and caret are handled below
                pass
            comp = _comparator_bounds(op, p)
            if comp is None:
                never = True
            else:
                bounds.extend(comp)
            i += 1
        for p in parsed:
            if p.pre:
                anchors.add(p.release)
    if never:
        bounds.append(("never", None))
    return bounds, anchors

